<?php require_once 'db.php'; $page_title='Create account'; csrf_check(); $err=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??''); $email=strtolower(trim($_POST['email']??'')); $pass=$_POST['password']??''; if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8){$err='Enter a name, valid email, and password of at least 8 characters.';}else{try{$s=db()->prepare("INSERT INTO users(name,email,password_hash) VALUES(?,?,?)");$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT)]);flash('Account created. Please sign in.');go('login.php');}catch(PDOException $e){$err='That email may already be registered.';}}} include 'header.php'; ?>
<section class="section" style="max-width:650px;margin:auto"><div class="eyebrow">JOIN US</div><h1 style="font-size:3rem">Create your account.</h1><?php if($err): ?><div class="notice"><?= h($err) ?></div><?php endif; ?><form class="panel" method="post"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><div class="field"><label>Full name</label><input name="name" required></div><div class="field"><label>Email</label><input name="email" type="email" required></div><div class="field"><label>Password (8+ characters)</label><input name="password" type="password" minlength="8" required></div><button class="btn">Create account</button><p class="muted">Already registered? <a href="login.php">Sign in</a></p></form></section><?php include 'footer.php'; ?>